    r = funcLuaCommand(1394177278)
    coroutine.yield()
  end
  BattleBayDeluxe.tournament_log("panel choice", r)
  if not keep or r < 0 then
    BattleBayDeluxe.tournament_choose_close()
  end
  return r
end

