-- Pieces drawn by one BattleBayDeluxe.tournament_draw
function BattleBayDeluxe.tournament_begin()
  BattleBayDeluxe.tournament_state.used = {}
  for _, l in pairs(BattleBayDeluxe.tournament.L) do
