    elseif S.want and not S.open then
      S.frames = S.frames + 1
      -- On a host with `cover` the screen stays black until the bracket is up, then fades in once.
      local cover = BattleBayDeluxe.tournament_host.cover == true
      if cover then
        funcLuaCommand(609722083 --[[fade black]], 1, 0)
      end
      if S.frames > 600 then
        S.want = false
        if cover then
          funcLuaCommand(609722083, 0, 0.3)
        end
      elseif S.frames > (cover and 2 or 20) and BattleBayDeluxe.tournament_host.ready()
        and (cover or funcLuaCommand(1215256347) ~= true) then
        S.want = false
        local ok, err = pcall(BattleBayDeluxe.tournament_open, -1)
        if not ok then
          BattleBayDeluxe.tournament_log("overlay error", tostring(err))
        end
        if cover then
          funcLuaCommand(609722083, 0, 0.3)
          BattleBayDeluxe.tournament_log("results shown under the cover after", S.frames, "Steps")
        end
      end
    end
    return table.unpack(r)
  end })
end
-- ===== EVT battlebaydeluxe_tournament top wraps END =====

-- ===== EVT battlebaydeluxe_tournament mode BEGIN =====
-- Switched with the rebindable CMD_BBD_MODE_SWITCH key (polled on MENU_CTRL) or a click on a pill.
--- Wraps global `name` once for `owner` with `parts`: `before` and `after` run in a pcall with the same arguments, `around(previous, ...)` makes the call; answers true, or false, why.
local function Wrap(owner, name, parts)
  local function failed(phase, err)
    if parts.on_error ~= nil then
      parts.on_error(err, phase)
    else
      VRFW.host.note(owner, name .. " " .. phase .. " error: " .. tostring(err))
    end
  end
  return VRFW.host.wrap_once(name, owner, function(previous, ...)
    if parts.before ~= nil then
      local ok, err = pcall(parts.before, ...)
      if not ok then
        failed("before", err)
      end
    end
    local results
    if parts.around ~= nil then
      results = table.pack(parts.around(previous, ...))
    else
      results = table.pack(previous(...))
    end
    if parts.after ~= nil then
      local ok, err = pcall(parts.after, ...)
      if not ok then
        failed("after", err)
      end
    end
    return table.unpack(results, 1, results.n)
  end)
end
