  -- Geometry in screen px (y down)
  CX = 960, Y = 34, BG_EXTRA = 6, BG_H = 56, PILL_W = 172, PILL_H = 44, PILL_GAP = 6, KEY_W = 40, GAP = 8, PAD = 10,
